from flask import Blueprint, jsonify, request
from app.models.problem import Problem
from app.database import db

def problem_bp():
    blueprint = Blueprint('problem', __name__, url_prefix='/problems')

    @blueprint.route('/', methods=['GET'])
    def get_problems():
        try:
            problems = Problem.query.all()
            problems_data = [problem.to_dict() for problem in problems]
            return jsonify({'problems': problems_data}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404
            return jsonify({'problem': problem.to_dict()}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/', methods=['POST'])
    def create_problem():
        try:
            data = request.get_json()
            new_problem = Problem(
                title=data.get('title'),
                description=data.get('description'),
                difficulty=data.get('difficulty')
            )
            db.session.add(new_problem)
            db.session.commit()
            return jsonify({'message': 'Problem created successfully', 'problem': new_problem.to_dict()}), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            data = request.get_json()
            problem.title = data.get('title', problem.title)
            problem.description = data.get('description', problem.description)
            problem.difficulty = data.get('difficulty', problem.difficulty)

            db.session.commit()
            return jsonify({'message': 'Problem updated successfully', 'problem': problem.to_dict()}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            db.session.delete(problem)
            db.session.commit()
            return jsonify({'message': 'Problem deleted successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    return blueprint

from flask import Blueprint, jsonify, request
from app.models.user import User
from app.database import db

def user_bp():
    user_blueprint = Blueprint('user', __name__, url_prefix='/users')

    @user_blueprint.route('/', methods=['GET'])
    def get_users():
        users = User.query.all()
        users_data = [{'id': user.id, 'username': user.username, 'email': user.email} for user in users]
        return jsonify(users_data), 200

    @user_blueprint.route('/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        user_data = {'id': user.id, 'username': user.username, 'email': user.email}
        return jsonify(user_data), 200

    @user_blueprint.route('/', methods=['POST'])
    def create_user():
        data = request.get_json()
        if not data or 'username' not in data or 'email' not in data:
            return jsonify({'error': 'Invalid input'}), 400
        new_user = User(username=data['username'], email=data['email'])
        db.session.add(new_user)
        db.session.commit()
        return jsonify({'message': 'User created successfully', 'id': new_user.id}), 201

    @user_blueprint.route('/<int:user_id>', methods=['PUT'])
    def update_user(user_id):
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400
        if 'username' in data:
            user.username = data['username']
        if 'email' in data:
            user.email = data['email']
        db.session.commit()
        return jsonify({'message': 'User updated successfully'}), 200

    @user_blueprint.route('/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        db.session.delete(user)
        db.session.commit()
        return jsonify({'message': 'User deleted successfully'}), 200

    return user_blueprint

from flask import Blueprint, jsonify, request
from app.models.solution import Solution
from app.database import db

def solution_bp():
    blueprint = Blueprint('solution', __name__)

    @blueprint.route('/solutions', methods=['GET'])
    def get_solutions():
        solutions = Solution.query.all()
        result = [solution.to_dict() for solution in solutions]
        return jsonify(result), 200

    @blueprint.route('/solutions/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        solution = Solution.query.get(solution_id)
        if solution is None:
            return jsonify({'error': 'Solution not found'}), 404
        return jsonify(solution.to_dict()), 200

    @blueprint.route('/solutions', methods=['POST'])
    def create_solution():
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400

        try:
            new_solution = Solution(**data)
            db.session.add(new_solution)
            db.session.commit()
            return jsonify(new_solution.to_dict()), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/solutions/<int:solution_id>', methods=['PUT'])
    def update_solution(solution_id):
        solution = Solution.query.get(solution_id)
        if solution is None:
            return jsonify({'error': 'Solution not found'}), 404

        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400

        try:
            for key, value in data.items():
                setattr(solution, key, value)
            db.session.commit()
            return jsonify(solution.to_dict()), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/solutions/<int:solution_id>', methods=['DELETE'])
    def delete_solution(solution_id):
        solution = Solution.query.get(solution_id)
        if solution is None:
            return jsonify({'error': 'Solution not found'}), 404

        try:
            db.session.delete(solution)
            db.session.commit()
            return jsonify({'message': 'Solution deleted successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    return blueprint
